from pathlib import Path
import sys,base64,zlib
root=Path(sys.argv[1]); base=root/'app/src/main/java/kz/kairat/organizer'
ui=base/'OrganizerUi.kt'; settings=base/'SettingsStore.kt'; strings=base/'AppStrings.kt'; gradle=root/'app/build.gradle.kts'; cloud=base/'CloudSync.kt'

s=settings.read_text()
marker='    fun clearSyncSession() = prefs.edit()\n        .remove("sync_id_token").remove("sync_refresh_token").remove("sync_uid").remove("sync_token_expiry").apply()'
assert marker in s
replacement='    var syncLastFingerprint: String\n        get() = prefs.getString("sync_last_fingerprint", "") ?: ""\n        set(v) = prefs.edit().putString("sync_last_fingerprint", v).apply()\n    var syncLastCloudUpdatedAt: Long\n        get() = prefs.getLong("sync_last_cloud_updated_at", 0L)\n        set(v) = prefs.edit().putLong("sync_last_cloud_updated_at", v).apply()\n    var syncLastSuccessAt: Long\n        get() = prefs.getLong("sync_last_success_at", 0L)\n        set(v) = prefs.edit().putLong("sync_last_success_at", v).apply()\n    fun clearSyncSession() = prefs.edit()\n        .remove("sync_id_token").remove("sync_refresh_token").remove("sync_uid").remove("sync_token_expiry")\n        .remove("sync_last_fingerprint").remove("sync_last_cloud_updated_at").remove("sync_last_success_at").apply()'
settings.write_text(s.replace(marker,replacement,1))
cloud.write_text(zlib.decompress(base64.b64decode("")).decode())

u=ui.read_text()
sig='@Composable private fun OrganizerHome(db:NoteDatabase,settings:SettingsStore,lang:String,onLanguage:(String)->Unit,dark:Boolean,onDark:(Boolean)->Unit,fontScale:Float,onFont:(Float)->Unit,buttonScale:Float,onButtonScale:(Float)->Unit,bold:Boolean,onBold:(Boolean)->Unit,onLock:()->Unit){\n    val context=LocalContext.current'
assert sig in u
ui.write_text(u.replace(sig,sig+'\n    CloudAutoSyncHost(db,settings,lang)',1))

b=gradle.read_text(); assert 'versionCode = 59' in b and 'versionName = "0.9.26"' in b
gradle.write_text(b.replace('versionCode = 59','versionCode = 60').replace('versionName = "0.9.26"','versionName = "0.9.27"'))
a=strings.read_text(); assert '0.9.26 (59)' in a; strings.write_text(a.replace('0.9.26 (59)','0.9.27 (60)'))

c=cloud.read_text()
assert 'Project ID' not in c and 'Web API key' not in c
assert 'Отправить с телефона' not in c and 'Получить из облака' not in c
assert 'private const val INTERNAL_PROJECT_ID' in c and 'private const val INTERNAL_API_KEY' in c
assert 'CloudAutoSyncHost(db,settings,lang)' in ui.read_text()
assert 'versionCode = 60' in gradle.read_text() and 'versionName = "0.9.27"' in gradle.read_text()
assert '0.9.27 (60)' in strings.read_text()
